   value = re.sub(r'\s+', ' ', value).strip()

   # Standardize the formatting of values
   if 'voluntary non-profit - private' in value:
       return 'Voluntary Non-Profit - Private'
   elif 'voluntary non-profit - church' in value:
       return 'Voluntary Non-Profit - Church'
   elif 'government - hospital district or authority' in value:
       return 'Government - Hospital District or Authority'
   elif 'proprietary' in value:
       return 'Proprietary'
   else:
       return value.capitalize()
return value

